API Gateway & Routing Layer.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway_boundary, "API Gateway & Routing Layer") {
    Component(Geo_Routing_Policy_Engine, "Geo-Routing Policy Engine", "Google Cloud Load Balancing & Apigee", "Handles regional geo-routing, TLS termination, and directs EU and US traffic to appropriate regional clusters.")
    Component(WebRTC_Signaling_Router, "WebRTC Signaling Router", "Envoy", "Routes SDP offers and manages real-time session negotiation for video consultations.")
    Component(JWT_Validation___Consent_Enforcement_Filter, "JWT Validation & Consent Enforcement Filter", "Apigee Policy Filter", "Validates tokens and verifies patient/clinician consent before requests reach core services.")
}

Rel(Geo_Routing_Policy_Engine, WebRTC_Signaling_Router, "Routes real-time signaling", "TCP / WebRTC")
Rel(JWT_Validation___Consent_Enforcement_Filter, Geo_Routing_Policy_Engine, "Enforces policies on incoming requests", "HTTPS")

@enduml

AI Inference Wrapper.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("ai_inference_wrapper", "AI Inference Wrapper") {
    Component(Inference Controller, "Inference Controller", "Python, FastAPI", "Manages incoming inference requests, routing them through sanitization and execution, and triggering audit logs.")
    Component(Regional Data Sanitizer, "Regional Data Sanitizer", "Python, Pandas", "Enforces regional data isolation and sanitizes input data to comply with GDPR and HIPAA mandates.")
    Component(Model Execution Engine, "Model Execution Engine", "Python, PyTorch, Vertex AI SDK", "Executes the AI symptom-checker model and interacts with the external AI Model Registry.")
    Component(Audit & Logging Interceptor, "Audit & Logging Interceptor", "Python middleware", "Captures audit and traceability logs asynchronously for regulatory compliance and AI output tracking.")
}

Rel(Inference Controller, Regional Data Sanitizer, "Passes input data for regional sanitization", "In-memory Python call")
Rel(Regional Data Sanitizer, Model Execution Engine, "Passes sanitized data for model execution", "In-memory Python call")
Rel(Inference Controller, Audit & Logging Interceptor, "Dispatches audit logs", "Async queue")

@enduml

Datastores.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Datastores container

Container_Boundary(Datastores, "Datastores") {
    Component(PrimaryOperationalDB, "Primary Operational DB", "Cloud SQL PostgreSQL per region", "Manages regional operational data, user profiles, and encrypted metadata.")
    Component(AIAuditStore, "AI Audit Store", "BigQuery per region", "Maintains tamper-evident, append-only logs for AI traceability and audits.")
    Component(ConsentEncryptionKeyStore, "Consent & Encryption Key Store", "Cloud KMS / Secret Manager per region", "Handles regional envelope encryption and consent mappings.")
}

Rel(PrimaryOperationalDB, ConsentEncryptionKeyStore, "Validates patient revocation flags", "Internal gRPC")

@enduml
